js:
var opts=[].slice.call(root.querySelectorAll('.opt'));
var rows=[].slice.call(root.querySelectorAll('.row'));
var bill=root.querySelector('.bill'), cta=root.querySelector('.cta');
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var year=false;
function priceOf(r){var m=+r.getAttribute('data-m');return year?Math.round(m*0.8):m;}
function tween(el,to){
  var from=+el.getAttribute('data-v')||0;
  el.setAttribute('data-v',to);
  if(reduce||from===to){el.textContent=to;return;}
  var t0=0;
  function step(now){
    if(!root.isConnected)return;
    if(!t0)t0=now;
    var k=Math.min(1,(now-t0)/420), e=1-Math.pow(1-k,3);
    el.textContent=Math.round(from+(to-from)*e);
    if(k<1)requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
function chosen(){
  for(var i=0;i<rows.length;i++){if(rows[i].getAttribute('aria-checked')==='true')return rows[i];}
  return rows[1];
}
function render(){
  root.classList.toggle('year',year);
  rows.forEach(function(r){tween(r.querySelector('.num'),priceOf(r));});
  var s=chosen(), p=priceOf(s), m=+s.getAttribute('data-m');
  cta.textContent='Continue with '+s.getAttribute('data-plan')+' · $'+p+'/mo';
  bill.textContent=year?('Billed $'+(p*12)+' yearly · you save $'+((m-p)*12)):'Billed monthly · cancel anytime';
}
opts.forEach(function(o,i){
  o.addEventListener('click',function(){
    year=o.getAttribute('data-cyc')==='y';
    opts.forEach(function(x){var on=x===o;x.classList.toggle('on',on);x.setAttribute('aria-checked',on?'true':'false');});
    render();
  });
  o.addEventListener('keydown',function(e){
    if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();var n=opts[(i+1)%opts.length];n.focus();n.click();}
  });
});
rows.forEach(function(r,i){
  r.addEventListener('click',function(){
    rows.forEach(function(x){x.setAttribute('aria-checked',x===r?'true':'false');x.tabIndex=x===r?0:-1;});
    render();
  });
  r.tabIndex=r.getAttribute('aria-checked')==='true'?0:-1;
  r.addEventListener('keydown',function(e){
    var d=e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0;
    if(d){e.preventDefault();var n=rows[(i+d+rows.length)%rows.length];n.focus();n.click();}
  });
});
render();

