js:
var rng=root.querySelector('.rng'), reqn=root.querySelector('.reqn'),
    tot=root.querySelector('.tot'), dec=root.querySelector('.dec'),
    inc=root.querySelector('.inc'), ovr=root.querySelector('.ovr'),
    ovl=root.querySelector('.ovl'), ovv=root.querySelector('.ovv'),
    fit=root.querySelector('.fit'), cta=root.querySelector('.cta');
var FREE=100000, RATE=0.12, FEE=16;
function stepVal(i){
  var n=10000*Math.pow(2500,i/24);
  var mag=Math.pow(10,Math.floor(Math.log(n)/Math.LN10)-1);
  return Math.round(n/mag)*mag;
}
function fmt(n){
  if(n>=1000000){var m=n/1000000;return (m>=10?m.toFixed(0):m.toFixed(1))+'M';}
  return Math.round(n/1000)+'k';
}
function render(){
  var n=stepVal(+rng.value);
  var billable=Math.max(0,n-FREE);
  var over=billable/10000*RATE;
  var total=FEE+over;
  var pct=(+rng.value)/(+rng.max)*100;
  rng.style.setProperty('--p',pct.toFixed(1)+'%');
  rng.setAttribute('aria-valuetext',fmt(n)+' requests per month');
  reqn.textContent=fmt(n);
  tot.textContent=Math.floor(total);
  dec.textContent='.'+(total%1).toFixed(2).slice(2);
  var f=Math.min(n,FREE)/n*100;
  inc.style.width=f.toFixed(1)+'%';
  ovr.style.width=(100-f).toFixed(1)+'%';
  ovl.textContent='Overage · '+(billable?fmt(billable):'none');
  ovv.textContent='$'+over.toFixed(2);
  var tier=n<=250000?'Starter':n<=5000000?'Growth':'Scale';
  fit.textContent='Best fit · '+tier;
  cta.textContent='Start '+tier;
}
rng.addEventListener('input',render);
render();

