var heads=[].slice.call(root.querySelectorAll('.ph'));
var sum=root.querySelector('.sum'), go=root.querySelector('.go');
function pick(btn){
  heads.forEach(function(h){h.setAttribute('aria-pressed',h===btn?'true':'false');});
  root.className=root.className.replace(/\s*sel[123]/g,'')+' sel'+btn.getAttribute('data-i');
  var name=btn.getAttribute('data-plan');
  sum.textContent=name+' · $'+btn.getAttribute('data-price')+' / user / mo';
  go.textContent='Choose '+name;
}
heads.forEach(function(h,i){
  h.addEventListener('click',function(){pick(h);});
  h.addEventListener('keydown',function(e){
    var d=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;
    if(d){e.preventDefault();var n=heads[(i+d+heads.length)%heads.length];n.focus();pick(n);}
  });
