var adds=[].slice.call(root.querySelectorAll('.ad'));
var qty=root.querySelector('.qty'), mn=root.querySelector('.mn'), pl=root.querySelector('.pl');
var num=root.querySelector('.num'), brk=root.querySelector('.brk');
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var seats=6, BASE=29, SEAT=7, FREE=3, MAX=50;
function tween(el,to){
  var from=+el.getAttribute('data-v')||0;
  el.setAttribute('data-v',to);
  if(reduce||from===to){el.textContent=to;return;}
  var t0=0;
  function step(now){
    if(!root.isConnected)return;
    if(!t0)t0=now;
    var k=Math.min(1,(now-t0)/380), e=1-Math.pow(1-k,3);
    el.textContent=Math.round(from+(to-from)*e);
    if(k<1)requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
function render(){
  var extra=Math.max(0,seats-FREE), on=0, addSum=0;
  adds.forEach(function(a){
    if(a.getAttribute('aria-checked')==='true'){on++;addSum+=+a.getAttribute('data-p');}
  });
  qty.textContent=seats;
  mn.disabled=seats<=1;
  pl.disabled=seats>=MAX;
  brk.textContent='base + '+extra+' paid seat'+(extra===1?'':'s')+' + '+on+' add-on'+(on===1?'':'s');
  tween(num,BASE+extra*SEAT+addSum);
}
adds.forEach(function(a){
  a.addEventListener('click',function(){
    a.setAttribute('aria-checked',a.getAttribute('aria-checked')==='true'?'false':'true');
    render();
  });
});
mn.addEventListener('click',function(){seats=Math.max(1,seats-1);render();});
pl.addEventListener('click',function(){seats=Math.min(MAX,seats+1);render();});
render();

