var seats=24, gb=200, mult=0, tier='Standard', prepay=true;
var el={
  seats:root.querySelector('.seats'), gb:root.querySelector('.gb'),
  k1:root.querySelector('.k1'), v1:root.querySelector('.v1'),
  k2:root.querySelector('.k2'), v2:root.querySelector('.v2'),
  k3:root.querySelector('.k3'), v3:root.querySelector('.v3'),
  k4:root.querySelector('.k4'), v4:root.querySelector('.v4'),
  neg:root.querySelector('.neg'), tt:root.querySelector('.ttv'),
  pre:root.querySelector('.pre')
};
var btns={
  sm:root.querySelector('.s-mn'), sp:root.querySelector('.s-pl'),
  gm:root.querySelector('.g-mn'), gp:root.querySelector('.g-pl')
};
var tiers=[].slice.call(root.querySelectorAll('.tr'));
function money(n){return n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function render(){
  var seatCost=seats*9, gbCost=gb*0.06, supCost=(seatCost+gbCost)*mult;
  var sub=seatCost+gbCost+supCost;
  var disc=prepay?sub*0.15:0;
  el.seats.textContent=seats;
  el.gb.textContent=gb;
  btns.sm.disabled=seats<=1; btns.sp.disabled=seats>=500;
  btns.gm.disabled=gb<=50; btns.gp.disabled=gb>=5000;
  el.k1.textContent='Seats '+seats+' × 9.00';
  el.v1.textContent=money(seatCost);
  el.k2.textContent='Storage '+gb+' GB';
  el.v2.textContent=money(gbCost);
  el.k3.textContent='Support '+tier+(mult?' +'+Math.round(mult*100)+'%':'');
  el.v3.textContent=money(supCost);
  el.neg.style.display=prepay?'':'none';
  el.k4.textContent='Prepay discount −15%';
  el.v4.textContent='−'+money(disc);
  el.tt.textContent='$'+money(sub-disc);
}
btns.sm.addEventListener('click',function(){seats=Math.max(1,seats-1);render();});
btns.sp.addEventListener('click',function(){seats=Math.min(500,seats+1);render();});
btns.gm.addEventListener('click',function(){gb=Math.max(50,gb-50);render();});
btns.gp.addEventListener('click',function(){gb=Math.min(5000,gb+50);render();});
tiers.forEach(function(t,i){
  function pick(){
    tiers.forEach(function(x){var on=x===t;x.classList.toggle('on',on);x.setAttribute('aria-checked',on?'true':'false');});
    mult=parseFloat(t.getAttribute('data-x'));
    tier=t.getAttribute('data-n');
    render();
  }
  t.addEventListener('click',pick);
  t.addEventListener('keydown',function(e){
    var d=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;
    if(d){e.preventDefault();var n=tiers[(i+d+tiers.length)%tiers.length];n.focus();n.click();}
  });
});
el.pre.addEventListener('click',function(){
  prepay=!prepay;
  el.pre.setAttribute('aria-pressed',prepay?'true':'false');
  render();
});
render();

