var input=root.querySelector('.in'), go=root.querySelector('.go'),
    msg=root.querySelector('.msg'), lnk=root.querySelector('.lnk');
var re=/^[^\s@]+@[^\s@,]+\.[a-z]{2,}$/i;
function submit(){
  var v=input.value.trim();
  if(!re.test(v)){
    input.setAttribute('aria-invalid','true');
    msg.className='msg err';
    msg.textContent=v?'That does not look like a work email.':'Enter your work email to get a quote.';
    input.focus();
    return;
  }
  input.removeAttribute('aria-invalid');
  root.classList.add('sent');
  msg.className='msg ok';
  msg.textContent='Thanks — a solutions engineer will reply to '+v+' within 4 business hours.';
}
go.addEventListener('click',submit);
input.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();submit();}});
input.addEventListener('input',function(){
  if(input.getAttribute('aria-invalid')==='true'&&re.test(input.value.trim())){
    input.removeAttribute('aria-invalid');
    msg.className='msg';
    msg.textContent='Typical reply in under 4 business hours.';
  }
});
lnk.addEventListener('click',function(){
  msg.className='msg ok';
  msg.textContent='Calendar slots open Tue–Thu, 09:00–17:00 CET.';
});

css:
.mdp-feature-matrix{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:#0c0d10;border:1px solid #1e2027;border-radius:12px;padding:11px;color:#dcdee4}
.mdp-feature-matrix .bar{display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap;margin-bottom:9px}
.mdp-feature-matrix .chips{display:flex;gap:3px}
.mdp-feature-matrix .ch{border:1px solid #23262e;background:#131519;color:#868b98;font:600 9.5px/1 inherit;letter-spacing:.03em;padding:5px 7px;border-radius:6px;cursor:pointer;transition:color .16s,background .16s,border-color .16s}
.mdp-feature-matrix .ch:hover{color:#e8eaf0;border-color:#33373f}
.mdp-feature-matrix .ch:focus-visible{outline:2px solid #fb7185;outline-offset:2px}
.mdp-feature-matrix .ch.on{color:#0b0709;background:#fb7185;border-color:#fb7185}
.mdp-feature-matrix .diff{border:1px solid #23262e;background:none;color:#7c8190;font:600 9.5px/1 inherit;padding:5px 7px;border-radius:6px;cursor:pointer;white-space:nowrap;transition:color .16s,border-color .16s}
.mdp-feature-matrix .diff:hover{color:#e8eaf0;border-color:#33373f}
.mdp-feature-matrix .diff:focus-visible{outline:2px solid #fb7185;outline-offset:2px}
.mdp-feature-matrix .diff[aria-pressed="true"]{color:#fb7185;border-color:rgba(251,113,133,.5);background:rgba(251,113,133,.1)}
.mdp-feature-matrix .cols{display:grid;grid-template-columns:1fr 30px 30px 30px;gap:0;padding:0 4px 6px;border-bottom:1px solid #1c1e25}
.mdp-feature-matrix .cols span{font-size:8.5px;letter-spacing:.12em;text-transform:uppercase;color:#6b707d;text-align:center}
.mdp-feature-matrix .cols .sp{text-align:left}
.mdp-feature-matrix .rows{display:flex;flex-direction:column}
.mdp-feature-matrix .rw{display:grid;grid-template-columns:1fr 30px 30px 30px;align-items:center;width:100%;border:0;border-bottom:1px solid #16181e;background:none;color:inherit;font:inherit;padding:7px 4px;cursor:default;text-align:left;transition:background .14s}
.mdp-feature-matrix .rw:hover{background:rgba(255,255,255,.04)}
.mdp-feature-matrix .rw:focus-visible{outline:2px solid #fb7185;outline-offset:-2px;border-radius:4px}
.mdp-feature-matrix .rw.hide{display:none}
.mdp-feature-matrix .lb{font-size:10.5px;color:#c3c7d1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdp-feature-matrix .c{justify-self:center;position:relative;width:11px;height:11px;border-radius:50%}
.mdp-feature-matrix .c.f{background:#fb7185;box-shadow:0 0 0 3px rgba(251,113,133,.14)}
.mdp-feature-matrix .c.p{border:1.5px solid #6f7481}
.mdp-feature-matrix .c.p::after{content:"";position:absolute;left:2.5px;top:2.5px;width:4px;height:4px;border-radius:50%;background:#9aa0ad}
.mdp-feature-matrix .c.n{background:#22252c;transform:scale(.5)}
.mdp-feature-matrix .cap{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:9px;flex-wrap:wrap}
.mdp-feature-matrix .key{display:flex;align-items:center;gap:4px;font-size:8.5px;color:#6b707d;white-space:nowrap}
.mdp-feature-matrix .key .c{width:8px;height:8px;margin-left:5px}
.mdp-feature-matrix .key .c.f{box-shadow:none}
.mdp-feature-matrix .det{flex:1;min-width:0;font-size:9.5px;line-height:1.35;color:#8e93a1;text-align:right}
@media (prefers-reduced-motion: reduce){
.mdp-feature-matrix .ch,.mdp-feature-matrix .diff,.mdp-feature-matrix .rw{transition:none}
}

js:
var chips=[].slice.call(root.querySelectorAll('.ch'));
var diff=root.querySelector('.diff');
var rows=[].slice.call(root.querySelectorAll('.rw'));
var det=root.querySelector('.det');
var cat='all', only=false;
var base='Hover a row for the detail.';
function same(r){
  var v=r.getAttribute('data-v').split(',');
  return v[0]===v[1]&&v[1]===v[2];
}
function apply(){
  var shown=0;
  rows.forEach(function(r){
    var hide=(cat!=='all'&&r.getAttribute('data-c')!==cat)||(only&&same(r));
    r.classList.toggle('hide',hide);
    if(!hide)shown++;
  });
  base=shown+' of '+rows.length+' rows shown.';
  if(!det.getAttribute('data-lock'))det.textContent=base;
}
chips.forEach(function(c){
  c.addEventListener('click',function(){
    cat=c.getAttribute('data-c');
    chips.forEach(function(x){var on=x===c;x.classList.toggle('on',on);x.setAttribute('aria-pressed',on?'true':'false');});
    apply();
  });
});
diff.addEventListener('click',function(){
  only=!only;
  diff.setAttribute('aria-pressed',only?'true':'false');
  apply();
});
rows.forEach(function(r){
  function show(){det.setAttribute('data-lock','1');det.textContent=r.getAttribute('data-d');}
  function clear(){det.removeAttribute('data-lock');det.textContent=base;}
  r.addEventListener('pointerenter',show);
  r.addEventListener('pointerleave',clear);
  r.addEventListener('focus',show);
  r.addEventListener('blur',clear);
});
apply();
